mapper.select:





   SELECT /* getImageReactionDtl */
          #{tagtType} AS TAGT_TYPE
        , #{tagtNumb} AS TAGT_NUMB
        , COALESCE(LC.LIKE_CNT, 0) AS LIKE_CNT
        , CASE WHEN UL.USER_NUMB IS NULL THEN #{commNo} ELSE #{commYes} END AS LIKE_YSNO
        , COALESCE(RC.REPL_CNT, 0) AS REPL_CNT
     FROM TM_USERXM OWNER
    JOIN TM_USERXM ACTOR
      ON ACTOR.USER_NUMB = #{userNumb}
     AND ACTOR.USER_STAT = #{userStatActive}
LEFT JOIN (  SELECT L.TAGT_TYPE
                  , L.TAGT_NUMB
                  , COUNT(*) AS LIKE_CNT
               FROM TB_LIKEXX L
               JOIN TM_USERXM U
                 ON U.USER_NUMB = L.USER_NUMB
                AND U.USER_STAT = #{userStatActive}
              WHERE L.TAGT_TYPE = #{tagtType}
                AND L.TAGT_NUMB = #{tagtNumb}
           GROUP BY L.TAGT_TYPE, L.TAGT_NUMB
          ) LC
       ON LC.TAGT_TYPE = #{tagtType}
      AND LC.TAGT_NUMB = #{tagtNumb}
LEFT JOIN TB_LIKEXX UL
       ON UL.USER_NUMB = #{userNumb}
      AND UL.TAGT_TYPE = #{tagtType}
      AND UL.TAGT_NUMB = #{tagtNumb}
LEFT JOIN (  SELECT R.TAGT_TYPE
                  , R.TAGT_NUMB
                  , COUNT(*) AS REPL_CNT
               FROM TB_REPLXX R
              WHERE R.TAGT_TYPE = #{tagtType}
                AND R.TAGT_NUMB = #{tagtNumb}
                AND R.DELT_YSNO = #{commNo}
           GROUP BY R.TAGT_TYPE, R.TAGT_NUMB
          ) RC
       ON RC.TAGT_TYPE = #{tagtType}
      AND RC.TAGT_NUMB = #{tagtNumb}
    WHERE OWNER.USER_NUMB = #{ownerUserNumb}
      AND OWNER.USER_STAT = #{userStatActive}
      AND (   (#{tagtType} = #{targetProfile} AND OWNER.PROF_NUMB = #{tagtNumb})
           OR (#{tagtType} = #{targetBackground} AND OWNER.BGIM_NUMB = #{tagtNumb})
          )

