/* setUser */
INSERT INTO TM_USERXM (
            PROF_NUMB
          , BGIM_NUMB
          , USER_IDXX
          , USER_NICK
          , USER_PROV
          , USER_ROLE
          , USER_STAT
          , ONBD_YSNO
          , INTR_CNTN
          , JOIN_DATE
) VALUES (  #{profNumb,jdbcType=NUMERIC}
          , #{bgimNumb,jdbcType=NUMERIC}
          , #{userIdxx}
          , #{userNick}
          , #{userProv,jdbcType=VARCHAR}
          , #{userRole}
          , #{userStat}
          , #{onbdYsno}
          , #{intrCntn,jdbcType=VARCHAR}
          , CURRENT_TIMESTAMP
)

/* setDefaultUserSetting */
INSERT IGNORE INTO TM_USSETX (
            USER_NUMB
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{userNumb}
          , CURRENT_TIMESTAMP(6)
          , CURRENT_TIMESTAMP(6)
)

/* uptUserLanguageSetting */
INSERT INTO TM_USSETX (
            USER_NUMB
          , ENGL_YSNO
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{userNumb}
          , #{englishYsno}
          , CURRENT_TIMESTAMP(6)
          , CURRENT_TIMESTAMP(6)
)
ON DUPLICATE KEY UPDATE
       ENGL_YSNO = VALUES(ENGL_YSNO)
     , UPDT_DATE = CURRENT_TIMESTAMP(6)

/* uptUserPrivacySetting */
INSERT INTO TM_USSETX (
            USER_NUMB
          , RSTA_YSNO
          , GOAL_YSNO
          , IMFD_YSNO
          , RPUB_YSNO
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{userNumb}
          , #{readingStatisticsYsno}
          , #{readingGoalYsno}
          , #{imageFeedYsno}
          , #{reportPublicDefaultYsno}
          , CURRENT_TIMESTAMP(6)
          , CURRENT_TIMESTAMP(6)
)
ON DUPLICATE KEY UPDATE
       RSTA_YSNO = VALUES(RSTA_YSNO)
     , GOAL_YSNO = VALUES(GOAL_YSNO)
     , IMFD_YSNO = VALUES(IMFD_YSNO)
     , RPUB_YSNO = VALUES(RPUB_YSNO)
     , UPDT_DATE = CURRENT_TIMESTAMP(6)

