UPDATE /* uptUserProfile */
       TM_USERXM
   SET USER_NICK = #{userNick}
     , INTR_CNTN = #{intrCntn,jdbcType=VARCHAR}

     , PROF_NUMB = #{profNumb}

     , PROF_DATE = CURRENT_TIMESTAMP(6)



     , BGIM_NUMB = #{bgimNumb}

     , BGIM_DATE = CURRENT_TIMESTAMP(6)


 WHERE USER_NUMB = #{userNumb}



UPDATE /* uptUserOnboarding */
       TM_USERXM
   SET USER_NICK = #{userNick}
     , ONBD_YSNO = #{commYes}
 WHERE USER_NUMB = #{userNumb}
   AND ONBD_YSNO = #{commNo}

