UPDATE /* uptUserStatus */
       TM_USERXM
   SET USER_STAT = #{userStat}
     , WTHD_DATE = #{wthdDate,jdbcType=TIMESTAMP}
     , DELT_DATE = #{deltDate,jdbcType=TIMESTAMP}
 WHERE USER_NUMB = #{userNumb}



UPDATE /* uptUserReplyDeleted */
       TB_REPLXX
   SET DELT_YSNO = #{commYes}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE USER_NUMB = #{userNumb}
   AND COALESCE(DELT_YSNO, #{commNo}) != #{commYes}

